// Read-only, no-payload Windows storage audit. No deletion or source writes.
using System;
using System.IO;
using System.Text;
using System.Collections.Generic;
using System.ComponentModel;
using System.Runtime.InteropServices;
using Microsoft.Win32.SafeHandles;
public static class SparkPhysicalAudit {
  [StructLayout(LayoutKind.Sequential)] struct Info { public uint Attributes; public System.Runtime.InteropServices.ComTypes.FILETIME Creation,Access,Write; public uint Volume,SizeHigh,SizeLow,Links,IndexHigh,IndexLow; }
  [StructLayout(LayoutKind.Sequential)] struct Standard { public long Allocation,End; public uint Links; public byte Pending,Directory; }
  [StructLayout(LayoutKind.Sequential)] struct Tag { public uint Attributes,Value; }
  [StructLayout(LayoutKind.Sequential,CharSet=CharSet.Unicode)] struct FindData { public uint Attributes; public System.Runtime.InteropServices.ComTypes.FILETIME Creation,Access,Write; public uint SizeHigh,SizeLow,Reserved0,Reserved1; [MarshalAs(UnmanagedType.ByValTStr,SizeConst=260)] public string Name; [MarshalAs(UnmanagedType.ByValTStr,SizeConst=14)] public string Alternate; }
  [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)] static extern SafeFileHandle CreateFileW(string p,uint access,uint share,IntPtr security,uint creation,uint flags,IntPtr template);
  [DllImport("kernel32.dll",SetLastError=true)] static extern bool GetFileInformationByHandle(SafeFileHandle h,out Info i);
  [DllImport("kernel32.dll",SetLastError=true)] static extern bool GetFileInformationByHandleEx(SafeFileHandle h,int c,out Standard i,uint n);
  [DllImport("kernel32.dll",SetLastError=true)] static extern bool GetFileInformationByHandleEx(SafeFileHandle h,int c,out Tag i,uint n);
  [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)] static extern IntPtr FindFirstFileW(string p,out FindData d);
  [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)] static extern bool FindNextFileW(IntPtr h,out FindData d);
  [DllImport("kernel32.dll")] static extern bool FindClose(IntPtr h);
  struct Key : IEquatable<Key> { public uint Volume; public ulong Id; public bool Equals(Key k){return Volume==k.Volume&&Id==k.Id;} public override bool Equals(object o){return o is Key&&Equals((Key)o);} public override int GetHashCode(){return Volume.GetHashCode()^Id.GetHashCode();} }
  struct Space { public long Bytes,Allocated; public Space(long b,long a){Bytes=b;Allocated=a;} }
  sealed class Totals { public long Files,Directories,Logical,Allocated,SmallFiles,SmallLogical,SmallAllocated,Links,Errors,MultiLink; public Dictionary<Key,Space> Unique=new Dictionary<Key,Space>(); public long UniqueLogical,UniqueAllocated; public void Add(Key k,Space s){if(!Unique.ContainsKey(k)){Unique.Add(k,s);UniqueLogical+=s.Bytes;UniqueAllocated+=s.Allocated;}} public void Merge(Totals t){Files+=t.Files;Directories+=t.Directories;Logical+=t.Logical;Allocated+=t.Allocated;SmallFiles+=t.SmallFiles;SmallLogical+=t.SmallLogical;SmallAllocated+=t.SmallAllocated;Links+=t.Links;Errors+=t.Errors;MultiLink+=t.MultiLink;if(Unique.Count<t.Unique.Count){var old=Unique;Unique=t.Unique;t.Unique=old;long u=UniqueLogical;UniqueLogical=t.UniqueLogical;t.UniqueLogical=u;u=UniqueAllocated;UniqueAllocated=t.UniqueAllocated;t.UniqueAllocated=u;}foreach(var p in t.Unique)Add(p.Key,p.Value);t.Unique.Clear();} }
  static TextWriter output; static long threshold,seenFiles,seenDirs,transientErrors,busyErrors; static string rootId,rootPath,firstIssue; static HashSet<string> excluded; static Dictionary<string,Totals> collections; static DateTime lastProgress; static bool summaryMode;
  static string Native(string p){if(p.StartsWith(@"\\?\"))return p;if(p.StartsWith(@"\\"))return @"\\?\UNC\"+p.Substring(2);return @"\\?\"+p;}
  static string Q(string s){var b=new StringBuilder("\"");foreach(char c in s){switch(c){case '\\':b.Append("\\\\");break;case '"':b.Append("\\\"");break;case '\r':b.Append("\\r");break;case '\n':b.Append("\\n");break;case '\t':b.Append("\\t");break;default:if(c<32)b.Append("\\u"+((int)c).ToString("x4"));else b.Append(c);break;}}return b.Append('"').ToString();}
  static string Purpose(string r){if(rootId=="app-data")return "active-user-data-protected-read-only";if(rootId=="mcc-halo1"||rootId=="editing-kit")return "original-required-native-runtime-or-tool-read-only";if(rootId=="external-p0")return "project-owned-historical-recovery-evidence-protected";string t=r.Split('/')[0];switch(t){case ".git":return "git-history-and-recovery-protected-pending-reference-audit";case "target":return "reproducible-build-output-selected-binaries-protected-pending-review";case ".toolchain":return "project-local-toolchain-required-or-reproducible-pending-registry-audit";case "node_modules":return "reinstallable-frontend-dependencies-pending-lockfile-review";case "preserved":return "indexed-unique-originals-and-recovery-protected";case "artifacts":return "mixed-generated-evidence-owned-review-required";case "tools":return "registered-native-tools-and-required-inputs";case "dist":case "test-results":case "playwright-report":return "generated-output-pending-reference-review";default:return "source-config-or-potentially-unique-protected";}}
  static string Numbers(Totals t){return "\"files\":"+t.Files+",\"directories\":"+t.Directories+",\"logicalBytes\":"+t.Logical+",\"allocatedFileBytes\":"+t.Allocated+",\"uniqueFileObjects\":"+t.Unique.Count+",\"uniqueLogicalBytes\":"+t.UniqueLogical+",\"uniqueAllocatedFileBytes\":"+t.UniqueAllocated+",\"smallFiles\":"+t.SmallFiles+",\"smallLogicalBytes\":"+t.SmallLogical+",\"smallAllocatedFileBytes\":"+t.SmallAllocated+",\"reparseEntries\":"+t.Links+",\"multiLinkEntries\":"+t.MultiLink+",\"errors\":"+t.Errors;}
  static void Error(string r,string action,Exception e,Totals t){t.Errors++;var native=e as Win32Exception;if((native!=null&&(native.NativeErrorCode==2||native.NativeErrorCode==3||native.NativeErrorCode==32||native.NativeErrorCode==33||native.NativeErrorCode==303))||e is FileNotFoundException||e is DirectoryNotFoundException||e is MovingDirectoryException)transientErrors++;else if(native!=null&&native.NativeErrorCode==5)busyErrors++;string detail=(native==null?"":"Win32="+native.NativeErrorCode+" ")+e.Message;if(firstIssue==null)firstIssue=r+": "+action+": "+detail;output.WriteLine("{\"type\":\"error\",\"root\":"+Q(rootId)+",\"relative\":"+Q(r)+",\"action\":"+Q(action)+",\"message\":"+Q(detail)+"}");}
  sealed class MovingDirectoryException : IOException { public MovingDirectoryException(string p) : base("Directory identity changed during live sampling: "+p) {} }
  static SafeFileHandle OpenMetadata(string p,bool dir,uint share){var h=CreateFileW(Native(p),dir?0x80000000u:0x80u,share,IntPtr.Zero,3,0x02200000u,IntPtr.Zero);if(h.IsInvalid){int n=Marshal.GetLastWin32Error();h.Dispose();throw new Win32Exception(n,p);}return h;}
  static SafeFileHandle Open(string p,bool dir){return OpenMetadata(p,dir,dir?3u:7u);}
  // A live sampler must not pin Rust's short-lived archive directories against
  // deletion. Keep the operation root/ancestors pinned and full audits unchanged.
  // Reopen each mutable path below before accepting its file-ID accounting.
  static SafeFileHandle OpenVisitDirectory(string p,int depth){return summaryMode&&depth>0?OpenMetadata(p,true,7u):Open(p,true);}
  static void RecheckLiveDirectory(string p,Info expected){using(var current=OpenMetadata(p,true,7u)){Info named;if(!GetFileInformationByHandle(current,out named))throw new Win32Exception();if((named.Attributes&0x400)!=0)throw new IOException("Live directory replaced by a reparse point: "+p);if((named.Attributes&0x10)==0||named.Volume!=expected.Volume||named.IndexHigh!=expected.IndexHigh||named.IndexLow!=expected.IndexLow)throw new MovingDirectoryException(p);}}

  static Totals Visit(string path,string relative,int depth){var total=new Totals();if(depth>(summaryMode?32:96)||(summaryMode&&seenFiles+seenDirs>=200000)){Error(relative,"inventory-bound",new IOException("Metadata inventory exceeds its depth/entry bound"),total);return total;}SafeFileHandle handle=null;try{
    handle=OpenVisitDirectory(path,depth);Info before;if(!GetFileInformationByHandle(handle,out before))throw new Win32Exception();if((before.Attributes&0x10)==0)throw new IOException("Directory changed to non-directory");
    if((before.Attributes&0x400)!=0){Tag tag;if(!GetFileInformationByHandleEx(handle,9,out tag,(uint)Marshal.SizeOf(typeof(Tag))))throw new Win32Exception();bool cloud=(tag.Value&0xFFFF0FFFu)==0x9000001Au;output.WriteLine("{\"type\":\"reparse-directory\",\"root\":"+Q(rootId)+",\"relative\":"+Q(relative)+",\"tag\":"+tag.Value+",\"cloudMetadataOnly\":"+(cloud?"true":"false")+",\"targetTraversed\":false}");total.Links++;if(summaryMode&&firstIssue==null)firstIssue=relative+": reparse directory refused";if(summaryMode||!cloud)return total;}
    total.Directories++;seenDirs++;FindData d;IntPtr find=FindFirstFileW(Native(path.TrimEnd('\\')+"\\*"),out d);if(find==new IntPtr(-1)){int err=Marshal.GetLastWin32Error();if(err!=2)throw new Win32Exception(err,path);}
    else try{do{if(summaryMode&&seenFiles+seenDirs>=200000){Error(relative,"entry-bound",new IOException("Metadata inventory exceeds200000 entries"),total);break;}if(d.Name=="."||d.Name=="..")continue;string child=path.TrimEnd('\\')+"\\"+d.Name;string rel=relative.Length==0?d.Name:relative+"/"+d.Name;if(excluded.Contains(Path.GetFullPath(child))){output.WriteLine("{\"type\":\"excluded-audit-output\",\"root\":"+Q(rootId)+",\"relative\":"+Q(rel)+"}");continue;}if((d.Attributes&0x10)!=0){total.Merge(Visit(child,rel,depth+1));continue;}
      try{using(var file=Open(child,false)){Info info;if(!GetFileInformationByHandle(file,out info))throw new Win32Exception();if((info.Attributes&0x10)!=0)throw new IOException("File changed to directory");Standard standard;if(!GetFileInformationByHandleEx(file,1,out standard,(uint)Marshal.SizeOf(typeof(Standard))))throw new Win32Exception();long length=(long)(((ulong)info.SizeHigh<<32)|info.SizeLow);Key key=new Key{Volume=info.Volume,Id=((ulong)info.IndexHigh<<32)|info.IndexLow};total.Files++;seenFiles++;total.Logical+=length;total.Allocated+=standard.Allocation;total.Add(key,new Space(length,standard.Allocation));if(info.Links>1)total.MultiLink++;
        bool small=length<threshold&&standard.Allocation<threshold;if(small&&!summaryMode){total.SmallFiles++;total.SmallLogical+=length;total.SmallAllocated+=standard.Allocation;string[] parts=rel.Split('/');string group=parts.Length>2?parts[0]+"/"+parts[1]:(parts.Length>1?parts[0]:"<root>");string ext=Path.GetExtension(d.Name).ToLowerInvariant();if(ext.Length>32)ext="<long-extension>";string ck=group+"\n"+ext;Totals ct;if(!collections.TryGetValue(ck,out ct)){ct=new Totals();collections.Add(ck,ct);}ct.Files++;ct.Logical+=length;ct.Allocated+=standard.Allocation;ct.Add(key,new Space(length,standard.Allocation));}
        if(!small||info.Links>1||(info.Attributes&0x400)!=0){uint tag=0;if((info.Attributes&0x400)!=0){Tag x;if(!GetFileInformationByHandleEx(file,9,out x,(uint)Marshal.SizeOf(typeof(Tag))))throw new Win32Exception();tag=x.Value;total.Links++;}output.WriteLine("{\"type\":\"file\",\"root\":"+Q(rootId)+",\"relative\":"+Q(rel)+",\"bytes\":"+length+",\"allocatedBytes\":"+standard.Allocation+",\"dev\":"+Q(info.Volume.ToString())+",\"ino\":"+Q(key.Id.ToString())+",\"links\":"+info.Links+",\"attributes\":"+info.Attributes+",\"reparseTag\":"+tag+",\"classification\":"+Q(Purpose(rel))+"}");}
      }}catch(Exception e){Error(rel,"file-metadata",e,total);}
      if(!summaryMode&&(DateTime.UtcNow-lastProgress).TotalSeconds>=15){Console.WriteLine("metadata root="+rootId+" files="+seenFiles+" directories="+seenDirs);output.Flush();lastProgress=DateTime.UtcNow;}
    }while(FindNextFileW(find,out d));int end=Marshal.GetLastWin32Error();if(end!=18)throw new Win32Exception(end,path);}finally{FindClose(find);}
    Info after;if(!GetFileInformationByHandle(handle,out after)||before.Volume!=after.Volume||before.IndexHigh!=after.IndexHigh||before.IndexLow!=after.IndexLow)throw new IOException("Directory identity changed");if(summaryMode&&depth>0)RecheckLiveDirectory(path,before);
  }catch(Exception e){Error(relative,"directory-metadata",e,total);}finally{if(handle!=null)handle.Dispose();}
    if(relative.Length==0||relative.IndexOf('/')<0||total.Logical>=threshold||total.UniqueAllocated>=threshold)output.WriteLine("{\"type\":\"directory\",\"root\":"+Q(rootId)+",\"relative\":"+Q(relative)+","+Numbers(total)+",\"classification\":"+Q(Purpose(relative))+"}");return total;
  }
  static List<SafeFileHandle> ProtectAncestors(string p){var result=new List<SafeFileHandle>();try{var chain=new List<string>();string current=Path.GetDirectoryName(p);while(current!=null){chain.Add(current);current=Path.GetDirectoryName(current);}chain.Reverse();foreach(string ancestor in chain){var h=Open(ancestor,true);result.Add(h);Info info;if(!GetFileInformationByHandle(h,out info))throw new Win32Exception();if((info.Attributes&0x400)!=0){Tag tag;if(!GetFileInformationByHandleEx(h,9,out tag,(uint)Marshal.SizeOf(typeof(Tag))))throw new Win32Exception();if((tag.Value&0xFFFF0FFFu)!=0x9000001Au)throw new IOException("Linked ancestor refused: "+ancestor);}}return result;}catch{foreach(var h in result)h.Dispose();throw;}}
  public static void Run(string[] ids,string[] roots,string outputPath,long minimum,string[] exclusions){summaryMode=false;if(ids.Length!=roots.Length)throw new ArgumentException();threshold=minimum;excluded=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(string x in exclusions)excluded.Add(Path.GetFullPath(x));excluded.Add(Path.GetFullPath(outputPath));using(output=new StreamWriter(new FileStream(outputPath,FileMode.CreateNew,FileAccess.Write,FileShare.Read),new UTF8Encoding(false))){output.WriteLine("{\"type\":\"header\",\"schemaVersion\":1,\"kind\":\"spark-readonly-physical-metadata-audit\",\"at\":"+Q(DateTime.UtcNow.ToString("o"))+",\"thresholdBytes\":"+threshold+",\"payloadsRead\":false,\"sourceMutationPerformed\":false,\"allocationMethod\":\"FileStandardInfo.Allocation; directory totals deduplicate volume/file IDs; allocation excludes filesystem metadata, compression/shared extent reclaimability\",\"linksFollowed\":false}");for(int i=0;i<roots.Length;i++){rootId=ids[i];rootPath=Path.GetFullPath(roots[i]).TrimEnd('\\');collections=new Dictionary<string,Totals>();seenFiles=seenDirs=0;lastProgress=DateTime.UtcNow;Totals t;var ancestors=ProtectAncestors(rootPath);try{t=Visit(rootPath,"",0);}finally{foreach(var h in ancestors)h.Dispose();}foreach(var p in collections){if(p.Value.Logical<threshold&&p.Value.UniqueAllocated<threshold)continue;int n=p.Key.IndexOf('\n');output.WriteLine("{\"type\":\"small-file-collection\",\"root\":"+Q(rootId)+",\"relative\":"+Q(p.Key.Substring(0,n))+",\"extension\":"+Q(p.Key.Substring(n+1))+","+Numbers(p.Value)+",\"classification\":"+Q(Purpose(p.Key))+"}");}output.WriteLine("{\"type\":\"root-summary\",\"root\":"+Q(rootId)+",\"path\":"+Q(rootPath)+","+Numbers(t)+"}");output.Flush();Console.WriteLine("complete root="+rootId+" files="+t.Files+" logical="+t.Logical+" allocated="+t.UniqueAllocated+" errors="+t.Errors);t.Unique.Clear();collections.Clear();}output.WriteLine("{\"type\":\"complete\",\"readOnly\":true,\"sourceMutationPerformed\":false}");}}
  // Operation-scoped stdout summary: reuse the native allocation/file-ID reader
  // without creating another scan archive or following any reparse directory.
  public static string Summary(string directory,string[] exemptNames){
    summaryMode=true;threshold=long.MaxValue;rootId="operation";rootPath=Path.GetFullPath(directory).TrimEnd('\\');
    output=TextWriter.Null;seenFiles=seenDirs=transientErrors=busyErrors=0;firstIssue=null;collections=new Dictionary<string,Totals>();
    excluded=new HashSet<string>(StringComparer.OrdinalIgnoreCase);
    foreach(string name in exemptNames){if(String.IsNullOrEmpty(name)||name==".."||name.IndexOfAny(new char[]{'/', '\\', ':'})>=0)throw new IOException("Invalid direct-child exclusion");excluded.Add(Path.Combine(rootPath,name));}
    var ancestors=ProtectAncestors(rootPath);Totals total;
    try{total=Visit(rootPath,"",0);}finally{foreach(var handle in ancestors)handle.Dispose();}
    string result="{\"type\":\"root-summary\",\"path\":"+Q(rootPath)+","+Numbers(total)+",\"transientErrors\":"+transientErrors+",\"busyErrors\":"+busyErrors+",\"processCpuMs\":"+System.Diagnostics.Process.GetCurrentProcess().TotalProcessorTime.TotalMilliseconds.ToString(System.Globalization.CultureInfo.InvariantCulture)+",\"firstIssue\":"+Q(firstIssue??"")+"}";
    total.Unique.Clear();collections.Clear();return result;
  }
}
